#include <iostream>
#include <string>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    std::regex regex("<[^>]*?>");
    std::regex_replace(html, regex,");
    return html;
}

int main() {
    std::string markdownText = "This is a **bold** text with *italic* text";
    std::string htmlText = markdownToHtml(markdownText);
    std::cout << htmlText << std::endl;
    return 0;
}
```

